   const link=data<{properties:{hashed_token:string}}>(await db.auth.admin.generateLink({type:'magiclink',email:employee.email}));const client=createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!,process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY||process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!,{auth:{persistSession:false,autoRefreshToken:false}}),auth=data<{session:{access_token:string}|null}>(await client.auth.verifyOtp({type:'magiclink',token_hash:link.properties.hashed_token}));requireValue(auth.session,'EMPLOYEE_SESSION_MISSING');
