  await nativeGps.getByRole('tab',{name:'Location source',exact:true}).click();await expect(nativeGps.getByRole('radio',{name:'GPS device',exact:true})).toHaveCount(0);await nativeGps.getByRole('button',{name:'Edit location source',exact:true}).click();await expect(nativeGps.getByRole('radio',{name:'GPS device',exact:true})).toBeChecked();await take(native,'gps-fleet-expo-phone.png');
  await nativeGps.getByRole('radio',{name:'Manually entered',exact:true}).click();await nativeGps.getByRole('button',{name:'Enter coordinates',exact:true}).click();await nativeGps.getByLabel('Latitude',{exact:true}).fill('40.015');await nativeGps.getByLabel('Longitude',{exact:true}).fill('-105.27');await expect.poll(async()=>{const map=await nativeGps.locator('.maplibregl-map').boundingBox(),point=await nativeGps.locator('[data-marker-id="manual-truck-location"]').boundingBox();return Boolean(map&&point&&point.x>=map.x&&point.x+point.width<=map.x+map.width&&point.y>=map.y&&point.y+point.height<=map.y+map.height);}).toBe(true);proof.nativeManualPointVisible=true;await take(native,'gps-entered-point-visible-expo.png');await expect(nativeGps.getByRole('button',{name:'Refresh',exact:true})).toBeDisabled();let nativeReads=0;const countNativeReads=(request:{url:()=>string;method:()=>string})=>{if(request.method()==='GET'&&new URL(request.url()).pathname==='/api/mobile/fleet/devices')nativeReads++;};native.on('request',countNativeReads);await native.waitForTimeout(31_000);native.off('request',countNativeReads);proof.nativeDirtyPolls=nativeReads;expect(nativeReads).toBe(0);
